create extension if not exists pgcrypto;
create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,fiscal_external_id uuid not null unique,status text not null,version bigint not null default 1);
create table if not exists locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations,code text not null,name text not null,fiscal_external_id uuid not null unique,status text not null,version bigint not null default 1,unique(organization_id,code));
create table if not exists registers(id uuid primary key default gen_random_uuid(),location_id uuid not null references locations,code text not null,fiscal_external_id uuid not null unique,status text not null,version bigint not null default 1,unique(location_id,code));
create table if not exists employees(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations,first_name text not null,last_name text not null,operator_code char(4) not null,fiscal_operator_id uuid,status text not null,version bigint not null default 1);
create table if not exists products(id uuid primary key default gen_random_uuid(),organization_id uuid references organizations,sku text not null,barcode text,name text not null,unit text not null,price numeric(18,2) not null,tax_group char(1) not null,status text not null,version bigint not null default 1);
create table if not exists shifts(id uuid primary key default gen_random_uuid(),register_id uuid not null references registers,employee_id uuid not null references employees,fiscal_shift_id uuid,state text not null,opening_cash numeric(18,2) not null default 0,closing_cash numeric(18,2),opened_at timestamptz not null,closed_at timestamptz,version bigint not null default 1);
create table if not exists orders(id uuid primary key default gen_random_uuid(),shift_id uuid not null references shifts,external_id text not null unique,fiscal_sale_id text unique,fiscal_operation_id text,state text not null,total numeric(18,2) not null,currency char(3) not null check(currency='EUR'),version bigint not null,created_at timestamptz not null,completed_at timestamptz);
create table if not exists order_lines(id uuid primary key,order_id uuid not null references orders,line_no integer not null,product_id uuid references products,name text not null,quantity numeric(18,3) not null,unit_price numeric(18,2) not null,tax_group char(1) not null,gross numeric(18,2) not null,snapshot jsonb not null,unique(order_id,line_no));
create table if not exists webhook_inbox(event_id text primary key,event_type text not null,aggregate_id text not null,aggregate_version bigint not null,payload jsonb not null,signature_valid boolean not null,received_at timestamptz not null,processed_at timestamptz);
create table if not exists outbox(id uuid primary key default gen_random_uuid(),aggregate_type text not null,aggregate_id uuid not null,aggregate_version bigint not null,type text not null,payload jsonb not null,created_at timestamptz not null,published_at timestamptz,unique(aggregate_type,aggregate_id,aggregate_version,type));
create table if not exists runtime_snapshots(aggregate text primary key,payload jsonb not null,version bigint not null,updated_at timestamptz not null);
create table if not exists minipos_state_rows(collection text not null,entity_key text not null,payload jsonb not null,updated_at timestamptz not null default now(),primary key(collection,entity_key));
create index if not exists minipos_state_rows_updated on minipos_state_rows(updated_at);
create table if not exists minipos_state_meta(singleton boolean primary key default true check(singleton),generation bigint not null,updated_at timestamptz not null default now());
